import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__device__ __forceinline__ float warp_reduce_sum_f32(float val) {
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(mask, val, offset);
    }
    return val;
}

extern "C" __global__
void sdp_fwd_kernel(const __half* __restrict__ Q,
                    const __half* __restrict__ K,
                    const __half* __restrict__ V,
                    __half* __restrict__ Out,
                    int B, int H, int S, int D,
                    float scale)
{
    // Grid mapping:
    // blockIdx.z -> batch index (b)
    // blockIdx.y -> head index (h)
    // blockIdx.x -> query index (qi)
    int b = blockIdx.z;
    int h = blockIdx.y;
    int qi = blockIdx.x;

    int tid = threadIdx.x;
    int nthreads = blockDim.x;

    // Shared memory layout:
    // [0 .. D-1]            -> q_sh (float)
    // [D .. 2*D-1]          -> acc_v_sh (float)
    extern __shared__ float smem[];
    float* q_sh = smem;
    float* acc_v_sh = q_sh + D;

    // Compute base row offset (in rows of length D) for (b,h)
    size_t bh_base_rows = ((size_t)b * (size_t)H + (size_t)h) * (size_t)S;

    const __half* q_row = Q + (bh_base_rows + (size_t)qi) * (size_t)D;
    __half* out_row = Out + (bh_base_rows + (size_t)qi) * (size_t)D;

    // Load Q[qi, :] into shared memory (float)
    int D2_load = D >> 1;
    const __half2* qh2 = reinterpret_cast<const __half2*>(q_row);
    for (int i = tid; i < D2_load; i += nthreads) {
        float2 fq = __half22float2(qh2[i]);
        int d0 = i * 2;
        q_sh[d0]     = fq.x;
        q_sh[d0 + 1] = fq.y;
        acc_v_sh[d0]     = 0.0f;
        acc_v_sh[d0 + 1] = 0.0f;
    }
    if ((D & 1) && tid == 0) {
        int last = D - 1;
        q_sh[last] = __half2float(q_row[last]);
        acc_v_sh[last] = 0.0f;
    }

    // Initialize running softmax parameters (only needed by thread 0)
    float m = -INFINITY;
    float l = 0.0f;

    __syncwarp();

    // Iterate over keys j
    for (int j = 0; j < S; ++j) {
        // Compute dot product s = Q[qi,:] . K[j,:]
        const __half* k_row = K + (bh_base_rows + (size_t)j) * (size_t)D;
        float local_sum = 0.0f;
        int D2_dot = D >> 1;
        const __half2* kh2 = reinterpret_cast<const __half2*>(k_row);
        for (int i = tid; i < D2_dot; i += nthreads) {
            float2 fk = __half22float2(kh2[i]);
            int d0 = i * 2;
            local_sum = __fmaf_rn(q_sh[d0], fk.x, local_sum);
            local_sum = __fmaf_rn(q_sh[d0 + 1], fk.y, local_sum);
        }
        if ((D & 1) && tid == 0) {
            int last = D - 1;
            float k_val = __half2float(k_row[last]);
            local_sum = __fmaf_rn(q_sh[last], k_val, local_sum);
        }
        // Warp-level reduction of local_sum to get sum across the warp
        float sum = warp_reduce_sum_f32(local_sum);
        int lane = threadIdx.x & 31;
        // Compute streaming softmax scalars in lane 0 and broadcast
        float alpha = 0.0f;
        float expv  = 0.0f;
        if (lane == 0) {
            float s = sum * scale;
            float m_new = fmaxf(m, s);
            float a = __expf(m - m_new);
            float e = __expf(s - m_new);
            l = a * l + e;
            m = m_new;
            alpha = a;
            expv  = e;
        }
        alpha = __shfl_sync(0xffffffffu, alpha, 0);
        expv  = __shfl_sync(0xffffffffu, expv, 0);
        // Update acc_v_sh[d] = alpha * acc_v_sh[d] + expv * V[j, d]
        const __half* v_row = V + (bh_base_rows + (size_t)j) * (size_t)D;
        int D2_upd = D >> 1;
        const __half2* vh2 = reinterpret_cast<const __half2*>(v_row);
        for (int i = tid; i < D2_upd; i += nthreads) {
            float2 fv = __half22float2(vh2[i]);
            int d0 = i * 2;
            float c0 = expv * fv.x;
            float c1 = expv * fv.y;
            acc_v_sh[d0]     = __fmaf_rn(alpha, acc_v_sh[d0], c0);
            acc_v_sh[d0 + 1] = __fmaf_rn(alpha, acc_v_sh[d0 + 1], c1);
        }
        if ((D & 1) && tid == 0) {
            int last = D - 1;
            float v_val = __half2float(v_row[last]);
            acc_v_sh[last] = __fmaf_rn(alpha, acc_v_sh[last], expv * v_val);
        }
    }

    // Normalize by l and write output
    float l_bcast = __shfl_sync(0xffffffffu, l, 0);
    float inv_l = 1.0f / l_bcast;
    int D2_out = D >> 1;
    __half2* out_h2 = reinterpret_cast<__half2*>(out_row);
    for (int i = tid; i < D2_out; i += nthreads) {
        int d0 = i * 2;
        float2 f;
        f.x = acc_v_sh[d0] * inv_l;
        f.y = acc_v_sh[d0 + 1] * inv_l;
        out_h2[i] = __floats2half2_rn(f.x, f.y);
    }
    if ((D & 1) && tid == 0) {
        int last = D - 1;
        out_row[last] = __float2half_rn(acc_v_sh[last] * inv_l);
    }
}

torch::Tensor sdp_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda(), "Q must be a CUDA tensor");
    TORCH_CHECK(K.is_cuda(), "K must be a CUDA tensor");
    TORCH_CHECK(V.is_cuda(), "V must be a CUDA tensor");
    TORCH_CHECK(Q.scalar_type() == at::kHalf, "Q must be float16 (Half)");
    TORCH_CHECK(K.scalar_type() == at::kHalf, "K must be float16 (Half)");
    TORCH_CHECK(V.scalar_type() == at::kHalf, "V must be float16 (Half)");
    TORCH_CHECK(Q.sizes() == K.sizes(), "Q and K must have the same shape");
    TORCH_CHECK(Q.sizes() == V.sizes(), "Q and V must have the same shape");
    TORCH_CHECK(Q.dim() == 4, "Expected Q to have shape [B, H, S, D]");

    auto B = (int)Q.size(0);
    auto H = (int)Q.size(1);
    auto S = (int)Q.size(2);
    auto D = (int)Q.size(3);

    auto Qc = Q.contiguous();
    auto Kc = K.contiguous();
    auto Vc = V.contiguous();

    auto Out = torch::empty_like(Qc);

    const __half* Qp = reinterpret_cast<const __half*>(Qc.data_ptr<at::Half>());
    const __half* Kp = reinterpret_cast<const __half*>(Kc.data_ptr<at::Half>());
    const __half* Vp = reinterpret_cast<const __half*>(Vc.data_ptr<at::Half>());
    __half* Outp = reinterpret_cast<__half*>(Out.data_ptr<at::Half>());

    dim3 grid((unsigned)S, (unsigned)H, (unsigned)B);
    int block = 32;
    int warps = (block + 31) / 32;
    size_t shmem = (size_t)D * sizeof(float)   // q_sh
                 + (size_t)D * sizeof(float);  // acc_v_sh
    float scale = 1.0f / sqrtf((float)D);

    auto stream = at::cuda::getCurrentCUDAStream();
    sdp_fwd_kernel<<<grid, block, shmem, stream.stream()>>>(Qp, Kp, Vp, Outp, B, H, S, D, scale);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return Out;
}

"""
_ext = load_inline(
    name="sdp_attn_ext",
    cpp_sources=[r"""
#include <torch/extension.h>
// Forward declaration of the function defined in the CUDA TU
torch::Tensor sdp_attention_forward(torch::Tensor Q,
                                    torch::Tensor K,
                                    torch::Tensor V);
"""],
    cuda_sources=[_src],
    functions=["sdp_attention_forward"],
    with_cuda=True,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        # Expect shapes [B, H, S, D], dtype float16, CUDA
        return _ext.sdp_attention_forward(Q, K, V)

# Keep same input generation helpers
batch_size = 2
num_heads = 32
sequence_length = 256
embedding_dimension = 1024

def get_inputs():
    Q = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    K = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    V = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    return [Q, K, V]

def get_init_inputs():
    return []

