        float2 fq = __half22float2(qh2[i]);
        int d0 = i * 2;
        q_sh[d0]     = fq.x;
        q_sh[d0 + 1] = fq.y;
        acc_v_sh[d0]     = 0.0f;
        acc_v_sh[d0 + 1] = 0.0f;
    }
