                float m_new = fmaxf(m, s);
                float alpha = __expf(m - m_new);
                float expv  = __expf(s - m_new);
                l = alpha * l + expv;
                m = m_new;
                scalars_sh[0] = alpha;
                scalars_sh[1] = expv;
            }
        }
        __syncthreads();
        // Update acc_v_sh[d] = alpha * acc_v_sh[d] + expv * V[j, d]
        const __half* v_row = V + (bh_base_rows + (size_t)j) * (size_t)D;
        float alpha = scalars_sh[0];
        float expv  = scalars_sh[1];
        int D2_upd = D >> 1;
        const __half2* vh2 = reinterpret_cast<const __half2*>(v_row);
        for (int i = tid; i < D2_upd; i += nthreads) {
            float2 fv = __half22float2(vh2[i]);
            int d0 = i * 2;
            float c0 = expv * fv.x;
            float c1 = expv * fv.y;
            acc_v_sh[d0]     = __fmaf_rn(alpha, acc_v_sh[d0], c0);
            acc_v_sh[d0 + 1] = __fmaf_rn(alpha, acc_v_sh[d0 + 1], c1);
        }
        if ((D & 1) && tid == 0) {
            int last = D - 1;
            float v_val = __half2float(v_row[last]);
            acc_v_sh[last] = __fmaf_rn(alpha, acc_v_sh[last], expv * v_val);
        }
        // No need for barrier here since next iteration's reduction only uses red_sh
    }

    // Normalize by l and write output
    if (tid == 0) {
        scalars_sh[2] = l;
    }
    __syncthreads();
    float inv_l = 1.0f / scalars_sh[2];
    int D2_out = D >> 1;
    __half2* out_h2 = reinterpret_cast<__half2*>(out_row);
    for (int i = tid; i < D2_out; i += nthreads) {
        int d0 = i * 2;
        float2 f;
        f.x = acc_v_sh[d0] * inv_l;
        f.y = acc_v_sh[d0 + 1] * inv_l;
        out_h2[i] = __floats2half2_rn(f.x, f.y);
    }
    if ((D & 1) && tid == 0) {
        int last = D - 1;
        out_row[last] = __float2half_rn(acc_v_sh[last] * inv_l);
    }
