import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__device__ __forceinline__ float warp_reduce_sum_f32(float val) {
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(mask, val, offset);
    }
    return val;
}

extern "C" __global__
void sdp_fwd_kernel(const __half* __restrict__ Q,
                    const __half* __restrict__ K,
                    const __half* __restrict__ V,
                    __half* __restrict__ Out,
                    int B, int H, int S, int D,
                    float scale)
{
    // Grid mapping:
    // blockIdx.z -> batch index (b)
    // blockIdx.y -> head index (h)
    // blockIdx.x -> query index (qi)
    int b = blockIdx.z;
    int h = blockIdx.y;
    int qi = blockIdx.x;

    int tid = threadIdx.x;
    int nthreads = blockDim.x;

    // Shared memory layout:
    // [0 .. D-1]            -> q_sh (float)
    // [D .. 2*D-1]          -> acc_v_sh (float)
    // [2*D .. 2*D + nthreads - 1] -> red_sh (float)
    // [2*D + nthreads .. ]  -> scalars_sh (float, size >= 4)
    extern __shared__ float smem[];
    float* q_sh = smem;
    float* acc_v_sh = q_sh + D;
    float* red_sh = acc_v_sh + D;
    int nwarps = (nthreads + 31) >> 5;
    float* scalars_sh = red_sh + nwarps;
    // Compute base row offset (in rows of length D) for (b,h)
    size_t bh_base_rows = ((size_t)b * (size_t)H + (size_t)h) * (size_t)S;

    const __half* q_row = Q + (bh_base_rows + (size_t)qi) * (size_t)D;
    __half* out_row = Out + (bh_base_rows + (size_t)qi) * (size_t)D;

    // Load Q[qi, :] into shared memory (float)
    int D2_load = D >> 1;
    const __half2* qh2 = reinterpret_cast<const __half2*>(q_row);
    for (int i = tid; i < D2_load; i += nthreads) {
        float2 fq = __half22float2(qh2[i]);
        int d0 = i * 2;
        q_sh[d0]     = fq.x;
        q_sh[d0 + 1] = fq.y;
        acc_v_sh[d0]     = 0.0f;
        acc_v_sh[d0 + 1] = 0.0f;
    }
    if ((D & 1) && tid == 0) {
        int last = D - 1;
        q_sh[last] = __half2float(q_row[last]);
        acc_v_sh[last] = 0.0f;
    }

    // Initialize running softmax parameters (only needed by thread 0)
    float m = -INFINITY;
    float l = 0.0f;

    __syncthreads();

    // Iterate over keys j
    for (int j = 0; j < S; ++j) {
        // Compute dot product s = Q[qi,:] . K[j,:]
        const __half* k_row = K + (bh_base_rows + (size_t)j) * (size_t)D;
        float local_sum = 0.0f;
        int D2_dot = D >> 1;
        const __half2* kh2 = reinterpret_cast<const __half2*>(k_row);
        for (int i = tid; i < D2_dot; i += nthreads) {
            float2 fk = __half22float2(kh2[i]);
            int d0 = i * 2;
            local_sum += q_sh[d0] * fk.x + q_sh[d0 + 1] * fk.y;
        }
        if ((D & 1) && tid == 0) {
            int last = D - 1;
            float k_val = __half2float(k_row[last]);
            local_sum += q_sh[last] * k_val;
        }
        // Warp-level reduction of local_sum to get partial sums per warp
        float sum = warp_reduce_sum_f32(local_sum);
        int lane = threadIdx.x & 31;
        int warp_id = threadIdx.x >> 5;
        if (lane == 0) {
            red_sh[warp_id] = sum;
        }
        __syncthreads();
        // Final reduce across warps using warp 0
        if (warp_id == 0) {
            float v = (lane < nwarps) ? red_sh[lane] : 0.0f;
            v = warp_reduce_sum_f32(v);
            if (lane == 0) {
                float s = v * scale;
                float m_new = fmaxf(m, s);
                float alpha = __expf(m - m_new);
                float expv  = __expf(s - m_new);
                l = alpha * l + expv;
                m = m_new;
                scalars_sh[0] = alpha;
                scalars_sh[1] = expv;
            }
        }
        __syncthreads();
        // Update acc_v_sh[d] = alpha * acc_v_sh[d] + expv * V[j, d]
        const __half* v_row = V + (bh_base_rows + (size_t)j) * (size_t)D;
        float alpha = scalars_sh[0];
        float expv  = scalars_sh[1];
        int D2_upd = D >> 1;
        const __half2* vh2 = reinterpret_cast<const __half2*>(v_row);
        for (int i = tid; i < D2_upd; i += nthreads) {
            float2 fv = __half22float2(vh2[i]);
            int d0 = i * 2;
            acc_v_sh[d0]     = alpha * acc_v_sh[d0]     + expv * fv.x;
            acc_v_sh[d0 + 1] = alpha * acc_v_sh[d0 + 1] + expv * fv.y;
        }
        if ((D & 1) && tid == 0) {
            int last = D - 1;
            float v_val = __half2float(v_row[last]);
            acc_v_sh[last] = alpha * acc_v_sh[last] + expv * v_val;
        }
        // No need for barrier here since next iteration's reduction only uses red_sh
    }

    // Normalize by l and write output
    if (tid == 0) {
        scalars_sh[2] = l;
    }
    __syncthreads();
    float inv_l = 1.0f / scalars_sh[2];
    int D2_out = D >> 1;
    __half2* out_h2 = reinterpret_cast<__half2*>(out_row);
    for (int i = tid; i < D2_out; i += nthreads) {
        int d0 = i * 2;
        float2 f;
        f.x = acc_v_sh[d0] * inv_l;
        f.y = acc_v_sh[d0 + 1] * inv_l;
        out_h2[i] = __floats2half2_rn(f.x, f.y);
    }
    if ((D & 1) && tid == 0) {
        int last = D - 1;
        out_row[last] = __float2half_rn(acc_v_sh[last] * inv_l);
    }
}

